<script setup>
import {ref,onMounted} from 'vue';import {api} from '../store';const items=ref([]),error=ref('');async function cargar(){try{items.value=await api('/historial')}catch(e){error.value=e.message}}async function borrar(x){if(!confirm('¿Eliminar informe?'))return;try{await api('/historial/'+x.id,'DELETE');await cargar()}catch(e){error.value=e.message}}onMounted(cargar);
</script><template><div class="page-heading"><div><div class="eyebrow">REPORTES</div><h2>Historial de análisis</h2><p>Recupera diagnósticos guardados y exporta sus resultados.</p></div><RouterLink to="/analisis" class="btn btn-primary">Nuevo análisis</RouterLink></div><div v-if="error" class="alert alert-danger">{{error}}</div><div class="card p-4"><div v-for="x in items" :key="x.id" class="task-row"><div class="task-icon"><i class="bi bi-file-earmark-bar-graph"></i></div><div class="flex-grow-1"><strong>{{x.titulo}}</strong><div class="small text-secondary">{{new Date(x.fecha).toLocaleString('es-PE')}}</div></div><RouterLink :to="'/analisis?historial='+x.id" class="btn btn-sm btn-outline-primary">Abrir informe</RouterLink><button class="btn btn-sm btn-outline-danger" @click="borrar(x)">Eliminar</button></div><p v-if="!items.length" class="empty-state">No hay análisis guardados.</p></div></template>